proposed_actions.suggested_command:
kubectl create configmap nginx-health -n profile --from-literal=healthz='OK'
# then patch the deployment to mount the configmap as a file at /usr/share/nginx/html/healthz (example patch shown below)
kubectl patch deployment profile-web -n profile --type='json' -p='[
  {"op":"add","path":"/spec/template/spec/volumes/-","value":{"name":"nginx-health","configMap":{"name":"nginx-health","items":[{"key":"healthz","path":"healthz"}]}}},
  {"op":"add","path":"/spec/template/spec/containers/0/volumeMounts/-","value":{"name":"nginx-health","mountPath":"/usr/share/nginx/html/healthz","subPath":"healthz","readOnly":true}}
]'

cat <<EOF | kubectl -n profile apply -f -
apiVersion: v1
kind: ConfigMap
metadata:
  name: profile-web-health
data:
  default.conf: |
    server {
      listen 80;
      location /healthz { return 200; }
      include /etc/nginx/conf.d/*.conf;
    }
EOF

# then mount this ConfigMap to override nginx conf in the Deployment (edit deployment to add volume and mount to /etc/nginx/conf.d/default.conf)
kubectl -n profile edit deployment profile-web
# Add a volume using configMap 'profile-web-health' and volumeMount to /etc/nginx/conf.d/default.conf (use subPath 'default.conf').
